import math
from sympy import isprime

def integer_power(base, exp):
    """Calculates base^exp for integer base and integer exponent, returning None if the result is not an integer."""
    if base == 0:
        if exp > 0:
            return 0
        elif exp == 0:
            # Conventionally 0^0 = 1 in some contexts, but let's treat it as undefined for safety unless we are forced.
            # However, since P must be a prime (>= 2), P=1 is not allowed.
            return 1 # Assuming 0^0 = 1 for now, will test if it helps.
        else: # exp < 0
            return None # Undefined (division by zero)

    if base == 1:
        return 1
    if base == -1:
        return 1 if exp % 2 == 0 else -1

    try:
        # Standard integer exponentiation for non-trivial cases
        result = base ** exp
        return result
    except OverflowError:
        # The number is too large, definitely not a small prime
        return None

def is_positive_prime(n):
    """Checks if n is a positive prime number."""
    return isinstance(n, int) and n > 1 and isprime(n)

def check_good_triple(x, y, z):
    """Checks if (x, y, z) is a good triple."""

    # Calculate factors
    try:
        factor1 = integer_power(y, x)
        factor2 = integer_power(z, y)
        factor3 = integer_power(x, z)
    except TypeError:
        # Should not happen if integer_power is robust, but as a safeguard
        return None

    if factor1 is None or factor2 is None or factor3 is None:
        return None # Not an integer product

    # Calculate the product P
    try:
        P = factor1 * factor2 * factor3
    except OverflowError:
        return None # Product too large

    if is_positive_prime(P):
        return P

# Search space: max(|x|, |y|, |z|) <= 3, so x, y, z in [-3, 3]
candidates = []
for x in range(-3, 4):
    for y in range(-3, 4):
        for z in range(-3, 4):
            P = check_good_triple(x, y, z)
            if P is not None:
                S = x**2 + y**2 + z**2
                candidates.append({
                    'triple': (x, y, z),
                    'P': P,
                    'S': S
                })

# Sort by S = x^2 + y^2 + z^2
candidates.sort(key=lambda c: c['S'])

# List results
results = []
for c in candidates:
    results.append((c['triple'], c['S']))

print("Found Good Triples (Triple, Sum of Squares):")
for result in results:
    print(result)

# Check the count to see if x_200 exists
print(f"Total number of good triples found: {len(results)}")

